#[derive(Clone)]
struct Evidence {
    events: Arc<Mutex<Vec<session::SessionEvent>>>,
    trace: Arc<Mutex<Vec<String>>>,
    models: Arc<Mutex<Vec<model::CompletionRequest>>>,
    tools: Arc<Mutex<Vec<tool::ExecuteRequest>>>,
}
#[rustfmt::skip]
fn scripted(model_outcomes:Vec<model::CompletionOutcome>,tool_outcome:tool::ExecuteOutcome,initial:Vec<session::SessionEvent>,load_failure:Option<session::SessionFailure>,conflict:u8)->(Composition,boxology_generated_contract::AgentLoopHandle,Evidence){
    use boxology_import_model_completion::test_support::ModelCompletionFake;use boxology_import_session_store::test_support::SessionStoreFake;use boxology_import_tool_runner::test_support::ToolRunnerFake;
    let evidence=Evidence{events:Arc::new(Mutex::new(initial)),trace:Arc::new(Mutex::new(Vec::new())),models:Arc::new(Mutex::new(Vec::new())),tools:Arc::new(Mutex::new(Vec::new()))};let queue=Arc::new(Mutex::new(VecDeque::from(model_outcomes)));let loads=Arc::new(AtomicUsize::new(0));
    let sessions=SessionStoreFake::new().with_load({let e=evidence.clone();move|_,_|{let n=loads.fetch_add(1,Ordering::SeqCst);e.trace.lock().unwrap().push("load".into());let events=e.events.lock().unwrap().clone();let failure=if n==0{load_failure.clone()}else{None};async move{Ok(if let Some(failure)=failure{session::LoadOutcome{result:None,failure:Some(failure)}}else{session::LoadOutcome{result:Some(session::LoadResult{next_sequence:events.len()as u64,events}),failure:None}})}}}).with_append({let e=evidence.clone();move|_,request|{e.trace.lock().unwrap().push(format!("append:{}",request.event.event_id));let mut events=e.events.lock().unwrap();let sequence=request.expected_sequence;let outcome=if conflict==0{events.push(session::SessionEvent{sequence,event_id:request.event.event_id,kind:request.event.kind,payload_json:request.event.payload_json});session::AppendOutcome{result:Some(session::AppendResult{sequence,appended:true}),failure:None}}else{if conflict==2{events.push(session::SessionEvent{sequence,event_id:format!("other-{sequence}"),kind:request.event.kind,payload_json:request.event.payload_json})}session::AppendOutcome{result:None,failure:Some(session_failure(session::SessionFailureClass::Local,"ambiguous",true))}};async move{Ok(outcome)}}});
    let model=ModelCompletionFake::new().with_complete({let e=evidence.clone();move|_,request|{e.trace.lock().unwrap().push("model".into());e.models.lock().unwrap().push(request);let outcome=queue.lock().unwrap().pop_front().unwrap();async move{Ok(outcome)}}});let tool=ToolRunnerFake::new().with_execute({let e=evidence.clone();move|_,request|{e.trace.lock().unwrap().push("tool".into());e.tools.lock().unwrap().push(request);let outcome=tool_outcome.clone();async move{Ok(outcome)}}});
    let descriptor=generated::implementation_descriptor();let capabilities:Vec<_>=descriptor.contract().capabilities().iter().map(|v|v.id().clone()).collect();let transport=Arc::new(StubTransport::new());let mut builder=CompositionBuilder::new();builder.add_box(descriptor,|imports|{let deps=generated::typed_imports(&imports);generated::factory(AgentLoopService::new(deps.model_completion,deps.tool_runner,deps.session_store),imports)});let consumer=BoxId::new("agent-loop").unwrap();builder.resolve_import(consumer.clone(),BoxId::new("model-completion").unwrap(),remote(model,model::contract_descriptor()));builder.resolve_import(consumer.clone(),BoxId::new("tool-runner").unwrap(),remote(tool,tool::contract_descriptor()));builder.resolve_import(consumer.clone(),BoxId::new("session-store").unwrap(),remote(sessions,session::contract_descriptor()));for capability in capabilities{builder.expose(consumer.clone(),capability,transport.clone(),ExposureLevel::CodeOnly);}let composition=builder.start().unwrap();let handle=boxology_generated_contract::AgentLoopHandle::from_erased(Arc::new(Exposure(transport.runtime().unwrap().exposures().to_vec())));(composition,handle,evidence)
}
