#[rustfmt::skip] fn completion(reason:model::FinishReason,content:Option<String>,calls:Vec<model::ToolCall>)->model::CompletionOutcome{model::CompletionOutcome{completion:Some(model::CompletionResult{content,tool_calls:calls,finish_reason:reason,usage:model::TokenUsage{input_tokens:1,output_tokens:1,total_tokens:2}}),failure:None}}
