#[test]
#[rustfmt::skip]
fn first_model_malformed_matrix_fails_before_tool_or_call_persistence(){let unknown=model::FinishReason::Unknown{tag:"Future".into(),payload:OpaquePayload::new(OpaqueTree::Null)};let malformed=[model::CompletionOutcome{completion:None,failure:None},model::CompletionOutcome{completion:Some(model::CompletionResult{content:None,tool_calls:vec![],finish_reason:model::FinishReason::ToolCalls,usage:model::TokenUsage{input_tokens:1,output_tokens:1,total_tokens:2}}),failure:Some(model::CompletionFailure{class:model::CompletionFailureClass::Local,code:"x".into(),message:"x".into(),retryable:false,retry_after_seconds:None})}];for outcome in malformed{let(_c,h,e)=scripted(vec![outcome],file_result(),vec![],None,0);assert!(internal(ready(h.run_turn(context(),request()))));assert_eq!((e.events.lock().unwrap().len(),e.tools.lock().unwrap().len()),(1,0));}let mut invalid_id=call("read",r#"{"path":"p"}"#.into());invalid_id.id="".into();let mut cases=vec![completion(model::FinishReason::ToolCalls,Some("text".into()),vec![call("read","{}".into())]),completion(model::FinishReason::ToolCalls,None,vec![]),completion(model::FinishReason::ToolCalls,None,vec![call("read","{}".into()),call("read","{}".into())]),completion(model::FinishReason::Length,None,vec![call("read","{}".into())]),completion(unknown,None,vec![call("read","{}".into())]),completion(model::FinishReason::ToolCalls,None,vec![invalid_id]),first("read","{"),first("read","[]"),first("read",&format!("{{\"path\":\"{}\"}}","x".repeat(LARGE))) ,first("write",r#"{"path":"p","content":"x"}"#)];for outcome in cases.drain(..){let(_c,h,e)=scripted(vec![outcome],file_result(),vec![],None,0);let failure=ready(h.run_turn(context(),request())).unwrap().failure.unwrap();assert!(matches!(failure.class,TurnFailureClass::Protocol));assert_eq!((e.events.lock().unwrap().len(),e.tools.lock().unwrap().len()),(1,0));}}

