fn second_model_protocol_matrix_stops_after_one_tool(){let cases=[completion(model::FinishReason::ToolCalls,None,vec![call("read","{}".into())]),completion(model::FinishReason::Length,Some("partial".into()),vec![]),completion(model::FinishReason::Stop,Some("".into()),vec![]),completion(model::FinishReason::Stop,Some("mixed".into()),vec![call("read","{}".into())]),completion(model::FinishReason::Stop,Some("x".repeat(LARGE+1)),vec![])];for outcome in cases{let(_c,h,e)=scripted(vec![first("read",r#"{"path":"p"}"#),outcome],file_result(),vec![],None,0);assert!(matches!(ready(h.run_turn(context(),request())).unwrap().failure.unwrap().class,TurnFailureClass::Protocol));assert_eq!((e.events.lock().unwrap().len(),e.tools.lock().unwrap().len()),(3,1));}}

#[test]
#[rustfmt::skip]
fn typed_dependency_failures_and_tool_control_are_truthfully_persisted(){let load=session_failure(session::SessionFailureClass::Local,"load_failed",false);let(_c,h,e)=scripted(vec![],file_result(),vec![],Some(load),0);let failure=ready(h.run_turn(context(),request())).unwrap().failure.unwrap();assert!(matches!(failure.class,TurnFailureClass::Session));assert!(!failure.side_effect_possible);assert!(e.events.lock().unwrap().is_empty());let model_failure=model::CompletionOutcome{completion:None,failure:Some(model::CompletionFailure{class:model::CompletionFailureClass::Transient,code:"model_failed".into(),message:"failed".into(),retryable:true,retry_after_seconds:None})};let(_c,h,e)=scripted(vec![model_failure],file_result(),vec![],None,0);let failure=ready(h.run_turn(context(),request())).unwrap().failure.unwrap();assert!(matches!(failure.class,TurnFailureClass::Model));assert!(failure.side_effect_possible);assert_eq!(e.events.lock().unwrap().len(),1);for(class,expected)in[(tool::ToolFailureClass::Cancelled,TurnFailureClass::Cancelled),(tool::ToolFailureClass::Deadline,TurnFailureClass::Deadline)]{let(_c,h,e)=scripted(vec![first("read",r#"{"path":"p"}"#)],tool_failure(class),vec![],None,0);let failure=ready(h.run_turn(context(),request())).unwrap().failure.unwrap();assert!(std::mem::discriminant(&failure.class)==std::mem::discriminant(&expected));let events=e.events.lock().unwrap();assert_eq!(events.len(),3);assert!(events[2].payload_json.contains("tool_failed"));assert_eq!(e.models.lock().unwrap().len(),1);}let(_c,h,e)=scripted(vec![first("read",r#"{"path":"p"}"#),second()],tool_failure(tool::ToolFailureClass::Local),vec![],None,0);assert!(ready(h.run_turn(context(),request())).unwrap().result.is_some());assert!(e.models.lock().unwrap()[1].messages.last().unwrap().content.as_ref().unwrap().contains("tool_failed"));}

