#[test]
#[rustfmt::skip]
fn input_matrix_is_rejected_before_imports(){let mut cases=Vec::new();for value in ["", "bad/id",&"x".repeat(65)]{let mut r=request();r.session_id=value.into();cases.push(r)}for value in ["", "bad/id",&"x".repeat(65)]{let mut r=request();r.turn_id=value.into();cases.push(r)}let mut r=request();r.max_output_tokens=Some(0);cases.push(r);let mut r=request();r.user_message="".into();cases.push(r);let mut r=request();r.user_message="x".repeat(TEXT+1);cases.push(r);let mut r=request();r.system_prompt="x".repeat(TEXT+1);cases.push(r);let mut r=request();r.tools.clear();cases.push(r);let mut r=request();r.tools=vec![r.tools[0].clone();17];cases.push(r);for(name,description,schema)in[("read","x",r#"{"type":"object"}"#.to_string()),("bad/name","x",r#"{}"#.into()),("nope","x",r#"{}"#.into()),("read",&"x".repeat(8193),r#"{}"#.into()),("read","x","[]".into()),("read","x","{".into()),("read","x",format!("{{\"x\":\"{}\"}}","x".repeat(TEXT)))]{let mut r=request();r.tools=vec![ModelTool{name:name.into(),description:description.into(),input_schema_json:schema}];if name=="read"&&description=="x"&&r.tools[0].input_schema_json.contains("type"){r.tools.push(r.tools[0].clone())}cases.push(r)}for request in cases{let trace=Arc::new(Mutex::new(Vec::new()));let(_c,h)=assembled(Arc::new(Mutex::new(Vec::new())),trace.clone(),Arc::new(AtomicUsize::new(0)),Arc::new(AtomicUsize::new(0)),false,0);assert!(matches!(ready(h.run_turn(context(),request)).unwrap().failure.unwrap().class,TurnFailureClass::Input));assert!(trace.lock().unwrap().is_empty());}}

#[test]
#[rustfmt::skip]
fn write_edit_bash_arguments_cross_generated_tool_import_exactly(){let cases=[("write",r#"{"path":"p","content":"c"}"#,false),("edit",r#"{"path":"p","old_text":"a","new_text":"b"}"#,false),("bash",r#"{"command":"pwd","cwd":"/tmp","timeout_ms":9}"#,true)];for(name,args,bash)in cases{let mut input=request();input.tools[0].name=name.into();let outcome=if bash{bash_result()}else{file_result_for(name)};let(_c,h,e)=scripted(vec![first(name,args),second()],outcome,vec![],None,0);assert!(ready(h.run_turn(context(),input)).unwrap().result.is_some());let request=e.tools.lock().unwrap()[0].clone();match name{"write"=>{let v=request.write.unwrap();assert_eq!((v.path,v.content),("p".into(),"c".into()))},"edit"=>{let v=request.edit.unwrap();assert_eq!((v.path,v.old_text,v.new_text),("p".into(),"a".into(),"b".into()))},"bash"=>{let v=request.bash.unwrap();assert_eq!((v.command,v.cwd,v.timeout_ms),("pwd".into(),Some("/tmp".into()),Some(9)))},_=>unreachable!()}}}

