fn persisted_wire_boundary_round_trips_and_escape_heavy_input_stops_before_append(){let mut accepted=request();accepted.user_message="a".repeat(TEXT);let(_c,h,e)=scripted(vec![first("read",r#"{"path":"p"}"#),second()],file_result(),vec![],None,0);assert!(ready(h.run_turn(context(),accepted.clone())).unwrap().result.is_some());let saved=e.events.lock().unwrap().clone();assert!(saved.iter().all(|event|event.payload_json.len()<=EVENT_WIRE));let(_fresh,replay,_)=scripted(vec![],file_result(),saved,None,0);assert_eq!(ready(replay.run_turn(context(),accepted)).unwrap().result.unwrap().answer,"done");let mut rejected=request();rejected.user_message="\0".repeat(TEXT);let(_c,h,e)=scripted(vec![],file_result(),vec![],None,0);let failure=ready(h.run_turn(context(),rejected)).unwrap().failure.unwrap();assert_eq!(failure.code,"event_payload_too_large");assert_eq!(*e.trace.lock().unwrap(),["load"]);assert!(e.events.lock().unwrap().is_empty());}

