async fn queued_deadline_returns_without_imports(){let trace=Arc::new(Mutex::new(Vec::new()));let entered=Arc::new(Notify::new());let release=Arc::new(Notify::new());let(_c,handle)=assembled_with_hold(Arc::new(Mutex::new(Vec::new())),trace.clone(),Arc::new(AtomicUsize::new(0)),Arc::new(AtomicUsize::new(0)),false,0,Some((entered.clone(),release.clone())));let first=tokio::spawn({let handle=handle.clone();async move{handle.run_turn(context(),request()).await}});entered.notified().await;let deadline=CallContext::new(Caller::Anonymous,Some(Deadline::at(Instant::now()+Duration::from_millis(1))),CancelToken::new(),TraceContext::empty(),None);let failure=handle.run_turn(deadline,request()).await.unwrap().failure.unwrap();assert!(matches!(failure.class,TurnFailureClass::Deadline));assert_eq!(*trace.lock().unwrap(),["load"]);release.notify_one();assert!(first.await.unwrap().unwrap().result.is_some());}

