#[test]
#[rustfmt::skip]
fn compact_appends_one_checkpoint_replays_idempotently_without_model_or_tool(){let(_c,h,e)=scripted(vec![],file_result(),completed_events(),None,0);let first=ready(h.compact(context(),compact_request())).unwrap().result.unwrap();assert_eq!((first.event_id.as_str(),first.sequence,first.appended),("checkpoint.cp-1",4,true));assert_eq!(*e.trace.lock().unwrap(),["load","append:checkpoint.cp-1"]);assert!(e.models.lock().unwrap().is_empty()&&e.tools.lock().unwrap().is_empty());let saved=e.events.lock().unwrap();assert_eq!(saved.len(),5);assert_eq!(serde_json::from_str::<Value>(&saved[4].payload_json).unwrap(),json!({"schema":"agent-loop-checkpoint@1","checkpoint_id":"cp-1","summary":"durable summary"}));drop(saved);e.trace.lock().unwrap().clear();let replay=ready(h.compact(context(),compact_request())).unwrap().result.unwrap();assert_eq!((replay.sequence,replay.appended),(4,false));assert_eq!(*e.trace.lock().unwrap(),["load"]);}

#[test]
#[rustfmt::skip]
fn fresh_turn_uses_checkpoint_and_post_checkpoint_context_only(){let(_c,h,e)=scripted(vec![],file_result(),completed_events(),None,0);assert!(ready(h.compact(context(),compact_request())).unwrap().result.is_some());let persisted=e.events.lock().unwrap().clone();let(_fresh,h,e)=scripted(vec![first("read",r#"{"path":"new"}"#),second()],file_result(),persisted,None,0);let mut next=request();next.turn_id="turn-2".into();next.user_message="new user".into();assert_eq!(ready(h.run_turn(context(),next)).unwrap().result.unwrap().answer,"done");let messages=&e.models.lock().unwrap()[0].messages;assert_eq!(messages.iter().filter_map(|v|v.content.as_deref()).collect::<Vec<_>>(),["be exact","durable summary","new user"]);assert_eq!(e.tools.lock().unwrap().len(),1);let persisted=e.events.lock().unwrap().clone();let(_newer,h,e)=scripted(vec![first("read",r#"{"path":"newest"}"#),second()],file_result(),persisted,None,0);let mut next=request();next.turn_id="turn-3".into();next.user_message="newest user".into();assert!(ready(h.run_turn(context(),next)).unwrap().result.is_some());let content=e.models.lock().unwrap()[0].messages.iter().filter_map(|v|v.content.clone()).collect::<Vec<_>>();assert!(content.contains(&"durable summary".into())&&content.contains(&"new user".into())&&content.contains(&"newest user".into()));assert!(!content.contains(&"old user".into())&&!content.contains(&"old answer".into()));}

