#[test]
#[rustfmt::skip]
fn adjacent_checkpoints_are_invalid_but_separated_generations_reset_context(){let mut adjacent=completed_events();adjacent.push(session::SessionEvent{sequence:4,event_id:"checkpoint.cp-1".into(),kind:session::SessionEventKind::Assistant,payload_json:r#"{"schema":"agent-loop-checkpoint@1","checkpoint_id":"cp-1","summary":"first summary"}"#.into()});adjacent.push(session::SessionEvent{sequence:5,event_id:"checkpoint.cp-2".into(),kind:session::SessionEventKind::Assistant,payload_json:r#"{"schema":"agent-loop-checkpoint@1","checkpoint_id":"cp-2","summary":"second summary"}"#.into()});let(_c,h,e)=scripted(vec![],file_result(),adjacent,None,0);let mut exact=compact_request();exact.summary="first summary".into();assert_eq!(ready(h.compact(context(),exact)).unwrap().failure.unwrap().code,"history_invalid");assert!(e.models.lock().unwrap().is_empty()&&e.tools.lock().unwrap().is_empty());let(_c,h,e)=scripted(vec![],file_result(),completed_events(),None,0);let mut cp1=compact_request();cp1.summary="first summary".into();assert!(ready(h.compact(context(),cp1)).unwrap().result.is_some());let persisted=e.events.lock().unwrap().clone();let(_fresh,h,e)=scripted(vec![first("read",r#"{"path":"between"}"#),second()],file_result(),persisted,None,0);let mut between=request();between.turn_id="between".into();between.user_message="between user".into();assert!(ready(h.run_turn(context(),between)).unwrap().result.is_some());let mut cp2=compact_request();cp2.checkpoint_id="cp-2".into();cp2.summary="second summary".into();assert!(ready(h.compact(context(),cp2)).unwrap().result.is_some());let persisted=e.events.lock().unwrap().clone();let(_newest,h,e)=scripted(vec![first("read",r#"{"path":"new"}"#),second()],file_result(),persisted,None,0);let mut newest=request();newest.turn_id="newest".into();newest.user_message="newest user".into();assert!(ready(h.run_turn(context(),newest)).unwrap().result.is_some());let content=e.models.lock().unwrap()[0].messages.iter().filter_map(|v|v.content.clone()).collect::<Vec<_>>();assert!(content.contains(&"second summary".into())&&content.contains(&"newest user".into()));assert!(!content.contains(&"first summary".into())&&!content.contains(&"between user".into())&&!content.contains(&"old user".into()));assert_eq!(e.tools.lock().unwrap().len(),1);}

