async fn queued_compact_cancellation_does_not_load_or_append(){let events=Arc::new(Mutex::new(completed_events()));let trace=Arc::new(Mutex::new(Vec::new()));let entered=Arc::new(Notify::new());let release=Arc::new(Notify::new());let(_c,h)=assembled_with_hold(events.clone(),trace.clone(),Arc::new(AtomicUsize::new(0)),Arc::new(AtomicUsize::new(0)),false,0,Some((entered.clone(),release.clone())));let holder=tokio::spawn({let h=h.clone();async move{h.run_turn(context(),request()).await}});entered.notified().await;let token=CancelToken::new();let queued_context=CallContext::new(Caller::Anonymous,None,token.clone(),TraceContext::empty(),None);let queued=tokio::spawn(async move{h.compact(queued_context,compact_request()).await});tokio::task::yield_now().await;assert_eq!(*trace.lock().unwrap(),["load"]);token.cancel();assert!(matches!(queued.await.unwrap().unwrap().failure.unwrap().class,TurnFailureClass::Cancelled));assert_eq!(*trace.lock().unwrap(),["load"]);release.notify_one();let _=holder.await.unwrap();assert!(events.lock().unwrap().iter().all(|event|!event.event_id.starts_with("checkpoint.")));}
